RouteModel::Node* start_node = &graph.SNodes()[start_idx];
RouteModel::Node* end_node = &graph.SNodes()[end_idx];

std::vector<RouteModel::Node*> open_list;
start_node->h_value = start_node->distance(*end_node);
start_node->g_value = 0.0f;
start_node->visited = true;
open_list.push_back(start_node);

while (!open_list.empty()) {
    auto current_it = std::min_element(open_list.begin(), open_list.end(),
        [](RouteModel::Node* a, RouteModel::Node* b) {
            return (a->g_value + a->h_value) < (b->g_value + b->h_value);
        });
    RouteModel::Node* current_node = *current_it;
    open_list.erase(current_it);

    if (current_node == end_node) {
        std::vector<RouteModel::Node> path;
        while (current_node != nullptr) {
            path.push_back(*current_node);
            current_node = current_node->parent;
        }
        std::reverse(path.begin(), path.end());
        return path;
    }

    current_node->find_neighbors();
    for (RouteModel::Node* neighbor : current_node->neighbors) {
        if (!neighbor->visited) {
            neighbor->parent = current_node;
            neighbor->g_value = current_node->g_value + current_node->distance(*neighbor);
            neighbor->h_value = neighbor->distance(*end_node);
            neighbor->visited = true;
            open_list.push_back(neighbor);
        } else {
            float tentative_g = current_node->g_value + current_node->distance(*neighbor);
            if (tentative_g < neighbor->g_value) {
                neighbor->parent = current_node;
                neighbor->g_value = tentative_g;
            }
        }
    }
}

return std::vector<RouteModel::Node>();

